"use client";
import { ZephyrPetalSignup, type ZephyrSignupValues } from "@/components/application/zephyr/petal-signup";

const stage = `
.zps-demo{display:grid;place-items:center;width:100%;padding:clamp(10px,3vw,40px);background:linear-gradient(180deg,#e8edef,#d7dee2)}
.zps-demo>*{max-width:1180px}
.frame-root .zps-demo{min-height:100svh}
`;

/** Stands in for a real sign-up: an address on taken.dev already has an account; any other one succeeds. */
async function signUp({ email }: ZephyrSignupValues) {
  await new Promise((resolve) => setTimeout(resolve, 900));
  if (email.toLowerCase().endsWith("@taken.dev")) return { ok: false as const, error: "That email already has an account", field: "email" as const };
  return { ok: true as const };
}

/**
 * Stillwater's sign-up beside the live scene. `still` shows the painted poster that stands in under reduced motion.
 * With `?capture` in the URL the scene is handed to `window.zephyrScene`, so a recording can step it frame by frame.
 */
export default function ZephyrPetalSignupDemo({ variant = "live" }: { variant?: string }) {
  const capture = typeof window !== "undefined" && new URLSearchParams(window.location.search).has("capture");
  return (
    <div className="zps-demo">
      <style>{stage}</style>
      <ZephyrPetalSignup
        still={variant === "still"}
        poster={variant === "still" ? undefined : "/assets/zephyr/petal-signup-poster.webp"}
        onSubmit={signUp}
        onScene={capture ? (scene) => Object.assign(window, { zephyrScene: scene }) : undefined}
      />
    </div>
  );
}

